DELETE wset FROM workout_sets wset
JOIN workout_sessions ws ON ws.id = wset.session_id
JOIN trainer_assignments ta ON ta.member_id = ws.member_id AND ta.status = 'ACTIVE'
JOIN trainers t ON t.id = ta.trainer_id
WHERE ws.member_id = #{memberId} AND DATE(ws.started_at) = #{workoutDate}
  AND t.user_id = #{userId}

DELETE ws FROM workout_sessions ws
JOIN trainer_assignments ta ON ta.member_id = ws.member_id AND ta.status = 'ACTIVE'
JOIN trainers t ON t.id = ta.trainer_id
WHERE ws.member_id = #{memberId} AND DATE(ws.started_at) = #{workoutDate}
  AND t.user_id = #{userId}
